def analyze_columns_by_region(grid):
    sep_idx = None
    for i, row in enumerate(grid):
        if all(x == 5 for x in row):
            sep_idx = i
            break

    top = grid[:sep_idx]
    bot = grid[sep_idx+1:]

    # Analyze each column in top region
    top_by_col = {}
    for col in range(len(grid[0])):
        col_vals = []
        for row in top:
            if col < len(row):
                col_vals.append(row[col])
        top_by_col[col] = col_vals

    # Analyze each column in bottom region
    bot_by_col = {}
    for col in range(len(grid[0])):
        col_vals = []
        for row in bot:
            if col < len(row):
                col_vals.append(row[col])
        bot_by_col[col] = col_vals

    # Get main columns with non-background values
    main_cols = []
    for col in range(len(grid[0])):
        if col in top_by_col and any(v not in (0, 5) for v in top_by_col[col]):
            if col in bot_by_col and any(v not in (0, 5) for v in bot_by_col[col]):
                main_cols.append(col)

    return top_by_col, bot_by_col, main_cols

